#!/usr/bin/env bash
set -euo pipefail

# cleanup.sh - Clean up temporary files
# Usage: ./cleanup.sh <VIDEO_ID> [--keep-state] [--force]
# Cleanup only runs for a completed run: the state file must record an
# `output_file` that exists on disk. Interrupted or failed runs keep their state
# and work files so they can be inspected and resumed; the script then exits 3
# without deleting anything. Pass --force to clean an unfinished run anyway.
# For a completed run this removes the state file as well, unless --keep-state
# is requested for debugging, plus chunk artifacts generated by
# transcribe-deepgram and chunk-text so the next run starts from a clean temp
# workspace.

if [ $# -lt 1 ]; then
    echo "Usage: $0 <VIDEO_ID> [--keep-state] [--force]" >&2
    exit 1
fi

VIDEO_ID="$1"
shift
KEEP_STATE=false
FORCE=false

if [ -z "$VIDEO_ID" ]; then
    echo "❌ Error: VIDEO_ID must not be empty" >&2
    exit 1
fi

case "$VIDEO_ID" in
    *[!A-Za-z0-9_-]*)
        echo "❌ Error: VIDEO_ID contains unsafe characters: $VIDEO_ID" >&2
        exit 1
        ;;
esac

for arg in "$@"; do
    case "$arg" in
        --keep-state) KEEP_STATE=true ;;
        --force) FORCE=true ;;
        *)
            echo "❌ Error: Unknown option: $arg" >&2
            exit 1
            ;;
    esac
done

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"
STATE_FILE="/tmp/${VIDEO_ID}_state.md"
MACHINE_STATE_FILE="/tmp/${VIDEO_ID}_machine_state.json"
KEEP_DIR=""

# A run is complete only when its state records an output_file that exists.
run_is_complete() {
    local output_file
    [ -f "$STATE_FILE" ] || return 1
    output_file=$(sed -n 's/^output_file:[[:space:]]*//p' "$STATE_FILE" | head -n 1 | sed 's/[[:space:]]*$//')
    [ -n "$output_file" ] || return 1
    case "$output_file" in
        "~/"*) output_file="$HOME/${output_file#\~/}" ;;
    esac
    [ -f "$output_file" ]
}

# Without a state file, only resumable chunk work marks the run as unfinished.
has_resumable_artifacts() {
    [ -f "$STATE_FILE" ] || [ -f "/tmp/${VIDEO_ID}_chunks/manifest.json" ]
}

if [ "$FORCE" != true ] && ! run_is_complete && has_resumable_artifacts; then
    echo "⏸️  Run for $VIDEO_ID is not finished (no final output_file recorded in $STATE_FILE)." >&2
    echo "   Keeping state and work files so the run can be resumed." >&2
    echo "   Inspect: python3 $ROOT_DIR/yt_transcript_utils.py find-unfinished --video-id $VIDEO_ID" >&2
    echo "   Discard anyway: bash $SCRIPT_DIR/cleanup.sh $VIDEO_ID --force" >&2
    exit 3
fi

echo "🧹 Cleaning up temporary files for video: $VIDEO_ID"

if [ "$KEEP_STATE" = true ]; then
    KEEP_DIR=$(mktemp -d)
    if [ -f "$STATE_FILE" ]; then
        mv "$STATE_FILE" "$KEEP_DIR/state.md"
    fi
    if [ -f "$MACHINE_STATE_FILE" ]; then
        mv "$MACHINE_STATE_FILE" "$KEEP_DIR/machine_state.json"
    fi
fi

# Remove all temp files related to this video
rm -f /tmp/${VIDEO_ID}.*
rm -f /tmp/${VIDEO_ID}_*.json
rm -f /tmp/${VIDEO_ID}_chunk_*
rm -f /tmp/${VIDEO_ID}_raw_text.txt
rm -f /tmp/${VIDEO_ID}_structured.txt
rm -f /tmp/${VIDEO_ID}_optimized.txt
rm -f /tmp/${VIDEO_ID}_combined_transcript.txt
rm -rf /tmp/${VIDEO_ID}_chunks/
rm -rf /tmp/${VIDEO_ID}_downloads/
if [ "$KEEP_STATE" != true ]; then
    rm -f "$STATE_FILE"
fi

if [ "$KEEP_STATE" = true ]; then
    if [ -f "$KEEP_DIR/state.md" ]; then
        mv "$KEEP_DIR/state.md" "$STATE_FILE"
    fi
    if [ -f "$KEEP_DIR/machine_state.json" ]; then
        mv "$KEEP_DIR/machine_state.json" "$MACHINE_STATE_FILE"
    fi
    rmdir "$KEEP_DIR" 2>/dev/null || true
fi

echo "✅ Cleanup complete"
